// Downloads the UI fonts into public/fonts/google/ so visitors never contact
// Google. Adapted from FantasticFrame's scripts/fetch-fonts.mjs (same family
// list as its UI font stack: Latin from IBM Plex Sans, CJK from Noto Sans SC).
//
// Output (git-ignored, regenerated by `yarn fonts`, dev and build):
//   *.woff2     one file per family/unicode-range slice/weight
//   fonts.css   @font-face rules, linked from nuxt.config
//
// Idempotent: skipped when fonts.css was generated for the same family list.
import { mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const FONTS = [
  { name: "IBM Plex Sans", weights: [400, 700] },
  { name: "Noto Sans SC", weights: [400, 700] },
];
const BASE = "/fonts/google";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const outDir = path.join(root, "public", BASE);
const UA =
  "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36";
const signature = `/* ${JSON.stringify(FONTS)} */`;

const slug = (s) => s.toLowerCase().replace(/[^a-z0-9]+/g, "-");

async function upToDate() {
  try {
    return (await readFile(path.join(outDir, "fonts.css"), "utf8")).startsWith(signature);
  } catch {
    return false;
  }
}

async function get(url, init) {
  for (let attempt = 1; ; attempt++) {
    try {
      const res = await fetch(url, init);
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      return res;
    } catch (err) {
      if (attempt >= 3) throw new Error(`${url}: ${err.message}`);
      await new Promise((r) => setTimeout(r, 500 * attempt));
    }
  }
}

async function mapLimit(items, limit, fn) {
  let i = 0;
  await Promise.all(
    Array.from({ length: limit }, async () => {
      while (i < items.length) await fn(items[i++]);
    }),
  );
}

if (await upToDate()) {
  console.log("[fonts] up to date");
  process.exit(0);
}

await mkdir(outDir, { recursive: true });
const css = [signature];
const downloads = [];

for (const { name, weights } of FONTS) {
  const family = `${name.replace(/ /g, "+")}:wght@${weights.join(";")}`;
  const sheet = await (
    await get(`https://fonts.googleapis.com/css2?family=${family}&display=swap`, {
      headers: { "User-Agent": UA },
    })
  ).text();

  let n = 0;
  for (const m of sheet.matchAll(/(?:\/\*\s*([^*]+?)\s*\*\/\s*)?@font-face\s*\{([^}]*)\}/g)) {
    const body = m[2];
    const url = body.match(/src:\s*url\(([^)]+)\)/)?.[1]?.replace(/['"]/g, "");
    const weight = Number(body.match(/font-weight:\s*(\d+)/)?.[1] ?? 400);
    const style = body.match(/font-style:\s*(\w+)/)?.[1] ?? "normal";
    const range = body.match(/unicode-range:\s*([^;]+)/)?.[1];
    if (!url) continue;
    const file = `${slug(name)}-${slug(m[1] ?? `s${n}`)}-${weight}.woff2`;
    n++;
    downloads.push({ url, file });
    css.push(
      `@font-face{font-family:"${name}";font-style:${style};font-weight:${weight};font-display:swap;` +
        `src:url(${BASE}/${file}) format("woff2");` +
        (range ? `unicode-range:${range};` : "") +
        `}`,
    );
  }
  if (n === 0) throw new Error(`no @font-face parsed for ${name}`);
  console.log(`[fonts] ${name}: ${n} slices`);
}

let done = 0;
await mapLimit(downloads, 8, async ({ url, file }) => {
  await writeFile(path.join(outDir, file), Buffer.from(await (await get(url)).arrayBuffer()));
  if (++done % 100 === 0) console.log(`[fonts] ${done}/${downloads.length} files`);
});

// Written last so an interrupted run is retried next time
await writeFile(path.join(outDir, "fonts.css"), css.join("\n") + "\n");
console.log(`[fonts] done: ${downloads.length} files`);
